package app;
import api.*;
import java.util.*;
final class SessionBook {
    private final String id;
    private final int capacity;
    private boolean open = true;
    private final Set<String> enrolled = new LinkedHashSet<>();
    private final List<String> waiting = new ArrayList<>();
    private final List<String> history = new ArrayList<>(List.of("open"));
    SessionBook(String id, int capacity) { this.id = id; this.capacity = capacity; }
    JoinStatus join(String participant) {
        requireOpen();
        if (enrolled.contains(participant) || waiting.contains(participant)) return JoinStatus.DUPLICATE;
        if (enrolled.size() < capacity) {
            enrolled.add(participant);
            history.add("join:"+participant+":enrolled");
            return JoinStatus.ENROLLED;
        }
        waiting.add(participant);
        history.add("join:"+participant+":waiting");
        return JoinStatus.WAITLISTED;
    }
    boolean leave(String participant) {
        requireOpen();
        if (waiting.remove(participant)) {
            history.add("leave:"+participant+":waiting");
            return true;
        }
        if (!enrolled.remove(participant)) return false;
        history.add("leave:"+participant+":enrolled");
        if (!waiting.isEmpty()) {
            String next = waiting.remove(0);
            enrolled.add(next);
            history.add("promote:"+next);
        }
        return true;
    }
    boolean close() {
        if (!open) return false;
        open = false;
        history.add("close");
        return true;
    }
    SessionView view() { return new SessionView(id, capacity, open, new ArrayList<>(enrolled), waiting, history); }
    private void requireOpen() { if (!open) throw new IllegalStateException("closed"); }
}

package app;
import api.*;
import java.util.*;
/** Public facade keeps catalog order; each book owns one session's mutable state. */
public final class WorkshopDesk implements DeskAPI {
    private final Map<String,SessionBook> sessions = new LinkedHashMap<>();
    public WorkshopDesk() {}
    public void open(String session, int capacity) {
        Rules.id(session, "session");
        Rules.capacity(capacity);
        if (sessions.containsKey(session)) throw new IllegalStateException("session");
        sessions.put(session, new SessionBook(session, capacity));
    }
    public JoinStatus join(String session, String participant) {
        Rules.id(session, "session"); Rules.id(participant, "participant");
        return book(session).join(participant);
    }
    public boolean leave(String session, String participant) {
        Rules.id(session, "session"); Rules.id(participant, "participant");
        return book(session).leave(participant);
    }
    public boolean close(String session) {
        Rules.id(session, "session"); return book(session).close();
    }
    public SessionView view(String session) {
        Rules.id(session, "session"); return book(session).view();
    }
    public List<SessionView> all() {
        List<SessionView> result = new ArrayList<>();
        for (SessionBook session : sessions.values()) result.add(session.view());
        return List.copyOf(result);
    }
    public String report(String style) {
        Rules.style(style);
        return DeskReports.render(all(), style);
    }
    private SessionBook book(String session) {
        SessionBook result = sessions.get(session);
        if (result == null) throw new NoSuchElementException("session");
        return result;
    }
}

package legacy;
import api.*;
import java.util.*;
/** Working before design: parallel maps and mixed registration/report responsibilities. */
public final class LegacyWorkshopDesk implements DeskAPI {
    private final Map<String,Integer> capacities = new LinkedHashMap<>();
    private final Map<String,Boolean> opened = new LinkedHashMap<>();
    private final Map<String,LinkedHashSet<String>> enrolled = new LinkedHashMap<>();
    private final Map<String,List<String>> waiting = new LinkedHashMap<>();
    private final Map<String,List<String>> histories = new LinkedHashMap<>();
    public LegacyWorkshopDesk() {}
    public void open(String session, int capacity) {
        Rules.id(session, "session");
        Rules.capacity(capacity);
        if (capacities.containsKey(session)) throw new IllegalStateException("session");
        capacities.put(session, capacity);
        opened.put(session, true);
        enrolled.put(session, new LinkedHashSet<>());
        waiting.put(session, new ArrayList<>());
        histories.put(session, new ArrayList<>(List.of("open")));
    }
    public JoinStatus join(String session, String participant) {
        Rules.id(session, "session");
        Rules.id(participant, "participant");
        if (!capacities.containsKey(session)) throw new NoSuchElementException("session");
        if (!opened.get(session)) throw new IllegalStateException("closed");
        if (enrolled.get(session).contains(participant) || waiting.get(session).contains(participant))
            return JoinStatus.DUPLICATE;
        if (enrolled.get(session).size() < capacities.get(session)) {
            enrolled.get(session).add(participant);
            histories.get(session).add("join:"+participant+":enrolled");
            return JoinStatus.ENROLLED;
        }
        waiting.get(session).add(participant);
        histories.get(session).add("join:"+participant+":waiting");
        return JoinStatus.WAITLISTED;
    }
    public boolean leave(String session, String participant) {
        Rules.id(session, "session");
        Rules.id(participant, "participant");
        if (!capacities.containsKey(session)) throw new NoSuchElementException("session");
        if (!opened.get(session)) throw new IllegalStateException("closed");
        if (waiting.get(session).contains(participant)) {
            waiting.get(session).remove(participant);
            histories.get(session).add("leave:"+participant+":waiting");
            return true;
        }
        if (enrolled.get(session).contains(participant)) {
            enrolled.get(session).remove(participant);
            histories.get(session).add("leave:"+participant+":enrolled");
            if (!waiting.get(session).isEmpty()) {
                String next = waiting.get(session).remove(0);
                enrolled.get(session).add(next);
                histories.get(session).add("promote:"+next);
            }
            return true;
        }
        return false;
    }
    public boolean close(String session) {
        Rules.id(session, "session");
        if (!capacities.containsKey(session)) throw new NoSuchElementException("session");
        if (!opened.get(session)) return false;
        opened.put(session, false);
        histories.get(session).add("close");
        return true;
    }
    public SessionView view(String session) {
        Rules.id(session, "session");
        if (!capacities.containsKey(session)) throw new NoSuchElementException("session");
        return new SessionView(session, capacities.get(session), opened.get(session),
            new ArrayList<>(enrolled.get(session)), waiting.get(session), histories.get(session));
    }
    public List<SessionView> all() {
        List<SessionView> result = new ArrayList<>();
        for (String id : capacities.keySet())
            result.add(new SessionView(id, capacities.get(id), opened.get(id),
                new ArrayList<>(enrolled.get(id)), waiting.get(id), histories.get(id)));
        return List.copyOf(result);
    }
    public String report(String style) {
        Rules.style(style);
        StringBuilder text = new StringBuilder();
        if (style.equals("plain")) {
            text.append("Workshops ").append(capacities.size()).append('\n');
            for (String id : capacities.keySet()) {
                text.append(id).append(" capacity=").append(capacities.get(id))
                    .append(" open=").append(opened.get(id)).append('\n');
                text.append("enrolled=").append(enrolled.get(id).isEmpty() ? "-" : String.join(",", enrolled.get(id))).append('\n');
                text.append("waiting=").append(waiting.get(id).isEmpty() ? "-" : String.join(",", waiting.get(id))).append('\n');
            }
        } else {
            text.append(capacities.size()).append('\n');
            for (String id : capacities.keySet()) {
                text.append(id).append('|').append(capacities.get(id)).append('|')
                    .append(opened.get(id) ? "open" : "closed").append('|')
                    .append(enrolled.get(id).isEmpty() ? "-" : String.join(",", enrolled.get(id))).append('|')
                    .append(waiting.get(id).isEmpty() ? "-" : String.join(",", waiting.get(id))).append('\n');
            }
        }
        return text.toString();
    }
}

package preview;
import api.*;
import java.util.*;
public final class RenamePreview {
    private RenamePreview() {}
    public static SessionView rename(SessionView source, String oldID, String newID) {
        Objects.requireNonNull(source, "snapshot");
        Rules.id(oldID, "oldID"); Rules.id(newID, "newID");
        if (!source.open()) throw new IllegalStateException("closed");
        boolean active = source.enrolled().contains(oldID);
        boolean queued = source.waiting().contains(oldID);
        if ((!active && !queued) || oldID.equals(newID)) return source;
        if (source.enrolled().contains(newID) || source.waiting().contains(newID))
            throw new IllegalArgumentException("newID");
        List<String> enrolled = new ArrayList<>(source.enrolled());
        List<String> waiting = new ArrayList<>(source.waiting());
        List<String> history = new ArrayList<>(source.history());
        List<String> selected = active ? enrolled : waiting;
        selected.set(selected.indexOf(oldID), newID);
        history.add("rename:"+oldID+":"+newID);
        return new SessionView(source.id(), source.capacity(), source.open(), enrolled, waiting, history);
    }
}

package trace;
import api.DeskAPI;
import java.util.*;
public final class Equivalence {
    private Equivalence() {}
    public static boolean same(DeskAPI before, DeskAPI after, List<Step> steps) {
        Objects.requireNonNull(before, "before");
        Objects.requireNonNull(after, "after");
        List<Step> plan = List.copyOf(Objects.requireNonNull(steps, "steps"));
        if (before == after) throw new IllegalArgumentException("independent desks");
        for (Step step : plan)
            if (!Observation.take(before, step).equals(Observation.take(after, step))) return false;
        return true;
    }
}

package trace;
import api.*;
import java.util.List;
public record Observation(String result, List<SessionView> sessions) {
    public Observation { sessions = List.copyOf(sessions); }
    public static Observation take(DeskAPI desk, Step step) {
        String result;
        try { result = "ok:"+step.run(desk); }
        catch (RuntimeException failure) {
            result = "error:"+failure.getClass().getName()+":"+String.valueOf(failure.getMessage());
        }
        return new Observation(result, desk.all());
    }
}

package trace;
import api.*;
public sealed interface Step permits Step.Open, Step.Join, Step.Leave, Step.Close, Step.Report {
    String run(DeskAPI desk);
    record Open(String session, int capacity) implements Step {
        public String run(DeskAPI desk) { desk.open(session, capacity); return "opened"; }
    }
    record Join(String session, String participant) implements Step {
        public String run(DeskAPI desk) { return desk.join(session, participant).name(); }
    }
    record Leave(String session, String participant) implements Step {
        public String run(DeskAPI desk) { return Boolean.toString(desk.leave(session, participant)); }
    }
    record Close(String session) implements Step {
        public String run(DeskAPI desk) { return Boolean.toString(desk.close(session)); }
    }
    record Report(String style) implements Step {
        public String run(DeskAPI desk) { return desk.report(style); }
    }
}

