package api;
public record BatchTotal(long raw,long usable,long lost) {
    public BatchTotal {
        if(raw<0||raw>72000000)throw new IllegalArgumentException("raw");
        if(usable<0||usable>raw)throw new IllegalArgumentException("usable");
        if(lost!=raw-usable)throw new IllegalArgumentException("lost");
    }
}

package api;
public record EnergyResult(int raw,int usable,int lost) {
    public EnergyResult {
        if(raw<0||raw>3600000)throw new IllegalArgumentException("raw");
        if(usable<0||usable>raw)throw new IllegalArgumentException("usable");
        if(lost!=raw-usable)throw new IllegalArgumentException("lost");
    }
}

package api;
public final class EnergyRules {
    private EnergyRules() {}
    public static void watts(int value) {if(value<0||value>1000)throw new IllegalArgumentException("watts");}
    public static void seconds(int value) {if(value<0||value>3600)throw new IllegalArgumentException("seconds");}
    public static void efficiency(int value) {if(value<0||value>100)throw new IllegalArgumentException("efficiency");}
}

package app;
import api.*;
public final class EnergyMeter implements EnergyAPI {
    public EnergyMeter() {}
    public EnergyResult measure(int watts,int seconds,int efficiency) {
        int raw=raw(watts,seconds);
        int usable=usable(raw,efficiency);
        return new EnergyResult(raw,usable,raw-usable);
    }
    public int raw(int watts,int seconds) {
        EnergyRules.watts(watts);EnergyRules.seconds(seconds);
        return watts*seconds;
    }
    public int usable(int raw,int efficiency) {
        if(raw<0||raw>3600000)throw new IllegalArgumentException("raw");
        EnergyRules.efficiency(efficiency);
        return raw*efficiency/100;
    }
}

package check;
import java.util.*;
public final class Checks {
    private static int count;
    private Checks() {}
    public static int count() { return count; }
    public static void yes(boolean value,String name) {
        count++;if(!value)throw new AssertionError(name);
    }
    public static void same(Object expected,Object actual,String name) {
        yes(Objects.equals(expected,actual),name+" expected="+expected+" actual="+actual);
    }
    public static void fails(Class<? extends RuntimeException> kind,String message,Runnable work) {
        count++;
        try{work.run();throw new AssertionError("missing "+kind.getSimpleName()+":"+message);}
        catch(RuntimeException failure) {
            if(failure.getClass()!=kind||!Objects.equals(message,failure.getMessage()))
                throw new AssertionError("wrong failure",failure);
        }
    }
    public static void immutable(List<?> list) {
        count++;try{list.clear();throw new AssertionError("mutable list");}
        catch(UnsupportedOperationException expected){ /* expected */ }
    }
}

